const string NOMES = "ABCDEF";
const int INFINITO = numeric_limits<int>::max();

vector<int> dijkstra(const Grafo &g, int origem, vector<int> &anterior) {
    vector<int> distancia(g.vertices(), INFINITO);
    anterior.assign(g.vertices(), -1);
