string caminho(const vector<int> &anterior, int destino) {
    string resultado;
    for (int v = destino; v != -1; v = anterior[v]) {   // volta pelos anteriores
        resultado += NOMES[v];
    }
    reverse(resultado.begin(), resultado.end());        // da origem ao destino
    return resultado;
}

